876	/// Resolve the top trigger from the stack.
877	/// Returns true if a trigger was resolved, false if the top of stack is not a trigger.
878	pub fn resolve_next_trigger(state: &mut GameState, registry: &CardRegistry) -> bool {
879	    // Check if the top of stack is a trigger.
880	    let is_trigger = state.stack.last()
881	        .map(|e| matches!(e, crate::state::StackEntry::Trigger(_)))
882	        .unwrap_or(false);
883	    if !is_trigger {
884	        return false;
885	    }
886	    let entry = state.stack.pop().expect("stack must have trigger entry");
887	    let trigger = match entry {
888	        crate::state::StackEntry::Trigger(t) => t,
889	        _ => unreachable!(),
890	    };
891	
892	    match trigger {
893	        PendingTrigger::EnteredBattlefield { object_id, card_id, .. } => {
894	            // Verify the object is still on the battlefield.
895	            if state.get_object(object_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
896	                if let Some(behavior) = registry.get(card_id) {
897	                    behavior.on_enter_battlefield(state, object_id, registry);
898	                }
899	            }
900	        }
901	        PendingTrigger::SelfDies { dead_id, dead_card_id, .. } => {
902	            if let Some(behavior) = registry.get(dead_card_id) {
903	                behavior.on_dies(state, dead_id, registry);
904	            }
905	        }
