1	//! Tests for card mechanics: morbid, leave-battlefield triggers,
2	//! forced attack, combat damage prevention, protection, token anthems,
3	//! opponent debuffs, conditional auras, unblockable, can't-block,
4	//! untap prevention.
5	
6	mod common;
7	
8	use common::*;
9	use mtg_engine::actions::{Action, Target};
10	use mtg_engine::cards::CardRegistry;
11	use mtg_engine::combat;
12	use mtg_engine::engine;
13	use mtg_engine::ids::{CardId, PlayerId};
14	use mtg_engine::sba::check_state_based_actions_with_registry;
15	use mtg_engine::triggers;
16	use mtg_engine::types::*;
17	
18	fn registry() -> CardRegistry {
19	    CardRegistry::with_all_cards()
20	}
21	
22	// ══════════════════════════════════════════════════════════════════
23	// Morbid
24	// ══════════════════════════════════════════════════════════════════
25	
26	/// creature_died_this_turn is set when a creature dies via SBA.
27	#[test]
28	fn morbid_flag_set_on_creature_death() {
29	    let reg = registry();
30	    let mut state = game_at_step(Step::PrecombatMain, P0);
31	    assert!(!state.creature_died_this_turn);
32	
33	    let creature = ready_creature(&mut state, P0, 1, 1);
34	    state.get_object_mut(creature).unwrap().damage_marked = 1;
35	
36	    check_state_based_actions_with_registry(&mut state, Some(&reg));
37	    assert!(state.creature_died_this_turn,
38	        "Morbid flag should be set after creature dies");
39	}
40	
41	/// creature_died_this_turn resets at start of new turn.
42	#[test]
